Subroutine Factorial(n As Integer) As Integer
  If n <= 1 Then
    Return 1;
  EndIf
  Return n * Factorial(n - 1);
EndSubroutine

Algorithm Principal
  Write Factorial(5);
EndAlgorithm

Subroutine EsPar(n As Integer) As Boolean
  If n = 0 Then
    Return True;
  EndIf
  Return EsImpar(n - 1);
EndSubroutine

Subroutine EsImpar(n As Integer) As Boolean
  If n = 0 Then
    Return False;
  EndIf
  Return EsPar(n - 1);
EndSubroutine

Algorithm Principal
  Write EsPar(10), " ", EsImpar(7);
EndAlgorithm

Subroutine SinFin(n As Integer) As Integer
  Return SinFin(n + 1);
EndSubroutine

Algorithm Principal
  Write SinFin(0);
EndAlgorithm
